package com.example.helpdesk.service; import com.example.helpdesk.model.*; import com.example.helpdesk.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class TicketService {private final TicketRepository tickets;private final UserRepository users;private final TicketHistoryRepository history;public TicketService(TicketRepository t,UserRepository u,TicketHistoryRepository h){tickets=t;users=u;history=h;}public List<Ticket> visible(User u,String q,Priority priority){List<Ticket> result;if(u.getRole()==Role.EMPLOYEE)result=tickets.findByReporterOrderByUpdatedAtDesc(u);else result=q==null||q.isBlank()?tickets.findAll():tickets.search(q);if(priority!=null)result=result.stream().filter(t->t.getPriority()==priority).toList();return result;}@Transactional public Ticket create(Ticket t,String name){User u=users.findByUsername(name).orElseThrow();if(t.getTitle()==null||t.getTitle().isBlank())throw new IllegalArgumentException("Title is required");t.setReporter(u);t.setStatus(TicketStatus.OPEN);if(t.getPriority()==null)t.setPriority(Priority.MEDIUM);Ticket saved=tickets.save(t);history.save(new TicketHistory(saved,u,"Created","Ticket submitted"));return saved;}public Ticket get(Long id){return tickets.findById(id).orElseThrow();}public List<TicketHistory> history(Long id){return history.findByTicketOrderByCreatedAtDesc(get(id));}@Transactional public void updateStatus(Long id,TicketStatus status,String notes,String name){Ticket t=get(id);if(status==TicketStatus.RESOLVED&&(notes==null||notes.isBlank()))throw new IllegalArgumentException("Resolution notes are required");t.setStatus(status);t.setResolutionNotes(notes);tickets.save(t);history.save(new TicketHistory(t,users.findByUsername(name).orElseThrow(),"Status changed","New status: "+status));}public long count(TicketStatus s){return tickets.countByStatus(s);}}
